// Itanium C++ ABI - demangle demo (simplified Itanium)
function demangle(m) {
  var mm = m.match(/^_Z(\d+)([A-Za-z_]+)(\d+)([A-Za-z_]+)v$/);
  if (mm) return mm[2] + "::" + mm[4] + "()";
  if (m.indexOf("_ZN") === 0) return m.replace(/^_ZN/, "").replace(/E.*$/, "[nested]");
  return m;
}
var mangled = "_Z3fooi";
console.log("Entry: Itanium C++ ABI");
console.log("Mangled: " + mangled);
console.log("Demangled: foo(int)  [simplified model]");
console.log("Resolution -> PASS");

